import base64, json, os, runpy, subprocess, sys, time
from pathlib import Path
os.environ.update(HF_HUB_DISABLE_XET="1", HF_HUB_DISABLE_PROGRESS_BARS="1", HF_HOME="/tmp/e49-hf",
                  PYTORCH_CUDA_ALLOC_CONF="expandable_segments:True")
started = time.time()
out = Path("/kaggle/working/e49-skywork")
out.mkdir(parents=True, exist_ok=True)
subprocess.run(["nvidia-smi"], check=True)
root = Path("/tmp/aimo-e49")
for name, encoded in json.loads('{"datagen/extract_budget_path_hf.py": "", "datagen/extract_budget_path.py": "", "datagen/extract_features.py": "", "datagen/tokenizer_check.py": "", "datagen/perturb/answers.py": "", "datagen/perturb/sample.py": "", "train/eval_e36_budget_path.py": "", "protocols/E49_PROTOCOL.md": "", "data/train_main/rows.parquet": "", "data/train_main/summary.json": "", "scripts/kaggle_process_guard.py": ""}').items():
    dest = root / name
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(base64.b64decode(encoded))
subprocess.run([sys.executable, "-m", "pip", "install", "--no-cache-dir", "-q", *['transformers==5.13.0', 'accelerate==1.13.0', 'huggingface-hub==1.22.0', 'tokenizers==0.22.2', 'safetensors==0.8.0', 'scikit-learn==1.8.0', 'joblib==1.5.3']], check=True)
freeze = subprocess.run([sys.executable, "-m", "pip", "freeze"], capture_output=True, text=True, check=True)
(out / "environment.txt").write_text(freeze.stdout)
cmd = [sys.executable, "datagen/extract_budget_path_hf.py", "--model-id", 'Skywork/Skywork-OR1-Math-7B', "--out-dir", str(out),
       "--dtype", "float16", "--max-batch-tokens", "150000", "--group-size", "0", "--max-hours", "10"]
result = runpy.run_path(str(root / "scripts/kaggle_process_guard.py"))["run_guarded"](cmd, root, out / "runner.log", timeout=39600)
(out / "execution.json").write_text(json.dumps({**result, "end_to_end_seconds": time.time() - started, "command": cmd}, indent=2))
raise SystemExit(result["exit_code"])
